# ComponentResource: Service Infrastructure Wrapper

Here's a complete Pulumi TypeScript ComponentResource wrapping S3, RDS PostgreSQL, and IAM.

## `serviceInfra.ts`

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import * as random from "@pulumi/random";

export interface ServiceInfraArgs {
    /** Environment name ("dev" | "prod") — drives sizing decisions. */
    environment: string;
    /** RDS instance class, e.g. "db.t3.micro" or "db.t3.medium". */
    dbInstanceClass: string;
    /** Enable multi-AZ deployment (prod). */
    dbMultiAz: boolean;
    /** Master DB username. */
    dbUsername: pulumi.Input<string>;
    /** Master DB password (should be a Pulumi secret). */
    dbPassword: pulumi.Input<string>;
    /** Backup retention in days (>= 7 required). */
    backupRetentionDays: number;
    /** VPC subnet IDs for the RDS subnet group (private subnets). */
    dbSubnetIds: pulumi.Input<string>[];
    /** Security group IDs to attach to RDS. */
    dbSecurityGroupIds: pulumi.Input<string>[];
    /** Optional KMS key ARN for RDS/S3 encryption. If omitted, AES256/aws-managed key used. */
    kmsKeyArn?: pulumi.Input<string>;
    /** OIDC provider ARN for IRSA trust (prod least-privilege role). */
    oidcProviderArn?: pulumi.Input<string>;
    /** OIDC provider URL (without https://). */
    oidcProviderUrl?: pulumi.Input<string>;
    /** Kubernetes namespace:serviceaccount for the OIDC subject. */
    serviceAccount?: string;
    /** Extra tags applied to all resources. */
    tags?: { [key: string]: string };
}

export class ServiceInfra extends pulumi.ComponentResource {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;
    public readonly roleArn: pulumi.Output<string>;

    constructor(
        name: string,
        args: ServiceInfraArgs,
        opts?: pulumi.ComponentResourceOptions,
    ) {
        super("myorg:infra:ServiceInfra", name, {}, opts);

        const isProd = args.environment === "prod";
        const parentOpts = { parent: this };
        const baseTags = {
            Environment: args.environment,
            ManagedBy: "pulumi",
            Component: "ServiceInfra",
            ...(args.tags ?? {}),
        };

        // Enforce acceptance criteria at construction time.
        if (args.backupRetentionDays < 7) {
            throw new Error(
                `backupRetentionDays must be >= 7 (got ${args.backupRetentionDays})`,
            );
        }

        // ------------------------------------------------------------------
        // 1. S3 BUCKET — versioning + encryption + no public access
        // ------------------------------------------------------------------
        const bucket = new aws.s3.BucketV2(
            `${name}-assets`,
            {
                tags: baseTags,
                // Prod buckets must be retained; dev can be torn down.
                forceDestroy: !isProd,
            },
            parentOpts,
        );

        new aws.s3.BucketVersioningV2(
            `${name}-assets-versioning`,
            {
                bucket: bucket.id,
                versioningConfiguration: { status: "Enabled" },
            },
            parentOpts,
        );

        new aws.s3.BucketServerSideEncryptionConfigurationV2(
            `${name}-assets-encryption`,
            {
                bucket: bucket.id,
                rules: [
                    {
                        applyServerSideEncryptionByDefault: args.kmsKeyArn
                            ? {
                                  sseAlgorithm: "aws:kms",
                                  kmsMasterKeyId: args.kmsKeyArn,
                              }
                            : { sseAlgorithm: "AES256" },
                        bucketKeyEnabled: true,
                    },
                ],
            },
            parentOpts,
        );

        // Block ALL public access.
        new aws.s3.BucketPublicAccessBlock(
            `${name}-assets-pab`,
            {
                bucket: bucket.id,
                blockPublicAcls: true,
                blockPublicPolicy: true,
                ignorePublicAcls: true,
                restrictPublicBuckets: true,
            },
            parentOpts,
        );

        // ------------------------------------------------------------------
        // 2. RDS POSTGRESQL — deletion protection, backups, private
        // ------------------------------------------------------------------
        const subnetGroup = new aws.rds.SubnetGroup(
            `${name}-db-subnets`,
            {
                subnetIds: args.dbSubnetIds,
                tags: baseTags,
            },
            parentOpts,
        );

        const db = new aws.rds.Instance(
            `${name}-db`,
            {
                engine: "postgres",
                engineVersion: "16",
                instanceClass: args.dbInstanceClass,
                allocatedStorage: isProd ? 100 : 20,
                maxAllocatedStorage: isProd ? 500 : 100,
                dbName: "appdb",
                username: args.dbUsername,
                password: args.dbPassword,
                dbSubnetGroupName: subnetGroup.name,
                vpcSecurityGroupIds: args.dbSecurityGroupIds,

                // --- Acceptance criteria ---
                multiAz: args.dbMultiAz,
                storageEncrypted: true,
                kmsKeyId: args.kmsKeyArn, // undefined => aws-managed key
                deletionProtection: true,
                backupRetentionPeriod: args.backupRetentionDays,
                publiclyAccessible: false,

                // Prod: snapshot on delete; dev: skip for fast teardown.
                skipFinalSnapshot: !isProd,
                finalSnapshotIdentifier: isProd
                    ? `${name}-db-final`
                    : undefined,

                applyImmediately: !isProd,
                autoMinorVersionUpgrade: true,
                copyTagsToSnapshot: true,
                tags: baseTags,
            },
            {
                ...parentOpts,
                // Extra guardrail: protect prod DB from accidental `pulumi destroy`.
                protect: isProd,
            },
        );

        // ------------------------------------------------------------------
        // 3. IAM ROLE — least privilege, OIDC trust for service accounts
        // ------------------------------------------------------------------
        // Build the assume-role (trust) policy.
        // Prod → OIDC/IRSA trust; dev → EC2/EKS node trust fallback.
        const assumeRolePolicy: pulumi.Output<string> =
            args.oidcProviderArn && args.oidcProviderUrl && args.serviceAccount
                ? pulumi
                      .all([
                          args.oidcProviderArn,
                          args.oidcProviderUrl,
                          args.serviceAccount,
                      ])
                      .apply(([providerArn, providerUrl, sa]) =>
                          JSON.stringify({
                              Version: "2012-10-17",
                              Statement: [
                                  {
                                      Effect: "Allow",
                                      Principal: { Federated: providerArn },
                                      Action: "sts:AssumeRoleWithWebIdentity",
                                      Condition: {
                                          StringEquals: {
                                              [`${providerUrl}:sub`]: `system:serviceaccount:${sa}`,
                                              [`${providerUrl}:aud`]:
                                                  "sts.amazonaws.com",
                                          },
                                      },
                                  },
                              ],
                          }),
                      )
                : pulumi.output(
                      JSON.stringify({
                          Version: "2012-10-17",
                          Statement: [
                              {
                                  Effect: "Allow",
                                  Principal: { Service: "ec2.amazonaws.com" },
                                  Action: "sts:AssumeRole",
                              },
                          ],
                      }),
                  );

        const role = new aws.iam.Role(
            `${name}-svc-role`,
            {
                assumeRolePolicy,
                tags: baseTags,
            },
            parentOpts,
        );

        // Scoped inline policy — only THIS bucket, no wildcard actions on prod.
        const policyDoc = pulumi
            .all([bucket.arn])
            .apply(([bucketArn]) => {
                const statements: any[] = [
                    {
                        Sid: "BucketListAndLocation",
                        Effect: "Allow",
                        Action: [
                            "s3:ListBucket",
                            "s3:GetBucketLocation",
                        ],
                        Resource: bucketArn,
                    },
                    {
                        Sid: "BucketObjectAccess",
                        Effect: "Allow",
                        // Explicit actions only — no s3:* even in dev.
                        Action: [
                            "s3:GetObject",
                            "s3:PutObject",
                            "s3:DeleteObject",
                        ],
                        Resource: `${bucketArn}/*`,
                    },
                ];
                return JSON.stringify({
                    Version: "2012-10-17",
                    Statement: statements,
                });
            });

        const policy = new aws.iam.Policy(
            `${name}-svc-policy`,
            {
                policy: policyDoc,
                description: `Least-privilege S3 access for ${name} (${args.environment})`,
                tags: baseTags,
            },
            parentOpts,
        );

        new aws.iam.RolePolicyAttachment(
            `${name}-svc-policy-attach`,
            {
                role: role.name,
                policyArn: policy.arn,
            },
            parentOpts,
        );

        // ------------------------------------------------------------------
        // Outputs
        // ------------------------------------------------------------------
        this.bucketName = bucket.id;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = db.endpoint;
        this.roleArn = role.arn;

        // Connection string is a SECRET — never logged in plaintext.
        this.dbConnectionString = pulumi.secret(
            pulumi
                .all([
                    args.dbUsername,
                    args.dbPassword,
                    db.address,
                    db.port,
                ])
                .apply(
                    ([user, pass, host, port]) =>
                        `postgresql://${user}:${pass}@${host}:${port}/appdb`,
                ),
        );

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            dbEndpoint: this.dbEndpoint,
            roleArn: this.roleArn,
            dbConnectionString: this.dbConnectionString,
        });
    }
}
```

## `index.ts` (stack entrypoint)

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ServiceInfra } from "./serviceInfra";

const config = new pulumi.Config();
const stack = pulumi.getStack(); // "dev" or "prod"

// Secrets are pulled from stack config (encrypted at rest via Pulumi).
const dbUsername = config.require("dbUsername");
const dbPassword = config.requireSecret("dbPassword");

// Networking inputs (from a network stack / config).
const dbSubnetIds = config.requireObject<string[]>("dbSubnetIds");
const dbSecurityGroupIds = config.requireObject<string[]>("dbSecurityGroupIds");

const infra = new ServiceInfra("app", {
    environment: stack,
    dbInstanceClass: config.require("dbInstanceClass"),
    dbMultiAz: config.requireBoolean("dbMultiAz"),
    dbUsername,
    dbPassword,
    backupRetentionDays: config.requireNumber("backupRetentionDays"),
    dbSubnetIds,
    dbSecurityGroupIds,
    kmsKeyArn: config.get("kmsKeyArn"),
    oidcProviderArn: config.get("oidcProviderArn"),
    oidcProviderUrl: config.get("oidcProviderUrl"),
    serviceAccount: config.get("serviceAccount"),
    tags: config.getObject<Record<string, string>>("tags"),
});

export const bucketName = infra.bucketName;
export const dbEndpoint = infra.dbEndpoint;
export const roleArn = infra.roleArn;
// Marked secret automatically — masked in `pulumi stack output`.
export const dbConnectionString = infra.dbConnectionString;
```

## Stack Configs

### `Pulumi.dev.yaml`

```yaml
config:
  aws:region: us-east-1
  app:dbInstanceClass: db.t3.micro
  app:dbMultiAz: "false"
  app:backupRetentionDays: "7"
  app:dbUsername: appuser
  # encrypted at rest by Pulumi's secrets provider
  app:dbPassword:
    secure: AAABAO...<ciphertext>...
  app:dbSubnetIds:
    - subnet-0dev1
    - subnet-0dev2
  app:dbSecurityGroupIds:
    - sg-0dev
  app:tags:
    Team: platform
```

Set the secret with:

```bash
pulumi config set --secret app:dbPassword 'S0meStr0ngP@ss' --stack dev
```

### `Pulumi.prod.yaml`

```yaml
config:
  aws:region: us-east-1
  app:dbInstanceClass: db.t3.medium
  app:dbMultiAz: "true"
  app:backupRetentionDays: "30"
  app:dbUsername: appuser
  app:dbPassword:
    secure: AAABAO...<ciphertext>...
  app:kmsKeyArn: arn:aws:kms:us-east-1:111122223333:key/abcd-...
  app:dbSubnetIds:
    - subnet-0prodA
    - subnet-0prodB
    - subnet-0prodC
  app:dbSecurityGroupIds:
    - sg-0prod
  # For IRSA (least-privilege OIDC trust)
  app:oidcProviderArn: arn:aws:iam::111122223333:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE
  app:oidcProviderUrl: oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE
  app:serviceAccount: app-namespace:app-serviceaccount
  app:tags:
    Team: platform
    Compliance: pci
```

## How This Meets the Acceptance Criteria

| Criterion | Implementation |
|---|---|
| **Bucket versioning** | `BucketVersioningV2` → `status: "Enabled"` |
| **Bucket encryption** | `BucketServerSideEncryptionConfigurationV2` (AES256, or `aws:kms` if `kmsKeyArn` set) |
| **Bucket no public access** | `BucketPublicAccessBlock` all four flags `true` |
| **RDS deletion protection** | `deletionProtection: true` + `protect: isProd` resource option |
| **RDS backups ≥ 7 days** | `backupRetentionPeriod` validated `>= 7` at construction |
| **RDS not public** | `publiclyAccessible: false`, private subnet group |
| **RDS encrypted (prod)** | `storageEncrypted: true` always; KMS key in prod config |
| **Secret never plaintext** | `pulumi.secret()` on connection string; `dbPassword` is `requireSecret` / encrypted in `Pulumi.*.yaml` |
| **IAM least privilege** | Explicit S3 actions only, scoped to this bucket ARN — no `s3:*` |
| **IAM OIDC trust (prod)** | `AssumeRoleWithWebIdentity` with `sub`/`aud` conditions |
| **Environment isolation** | Separate stacks (`dev`/`prod`), independent state & config |

## Notes

- **Cluster (EKS) and HTTPS/CloudFront** from the full spine are intentionally *not* in this component — this task scopes to **bucket + DB + IAM**. They'd compose as sibling ComponentResources (e.g. `ClusterInfra`, `EdgeInfra`) under the same stack.
- `protect: isProd` gives a hard guardrail against `pulumi destroy` on prod, complementing RDS `deletionProtection`.
- The RDS master password path shown uses a Pulumi secret; for production you may prefer `manageMasterUserPassword: true` to offload rotation to AWS Secrets Manager (drop the `password` field then).

